    customerId: 'C-001', // Gold (5%)
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }], // 10 * 9500 = 95000, 5% discount = 4750
  }).value;

  const totals = invoiceTotals(invoice);

  assert.equal(totals.ok, true);
  assert.equal(totals.value.subtotal, 95000);
  assert.equal(totals.value.discount, 4750);
  // net = 95000 - 4750 = 90250
  // vat = roundCents(90250 * 21 / 100) = roundCents(18952.5) = 18952
  assert.equal(totals.value.vat, 18952);
  // total = 95000 - 4750 + 18952 = 109202
  assert.equal(totals.value.total, 109202);
});

test('invoiceTotals includes VAT field', () => {
  const invoice = createInvoice({
    customerId: 'C-002', // Standard (0% discount)
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }], // 9500, no discount, 21% VAT
  }).value;

  const totals = invoiceTotals(invoice);

  assert.equal(totals.ok, true);
  assert.equal(totals.value.subtotal, 9500);
  assert.equal(totals.value.discount, 0);
  // vat = roundCents(9500 * 21 / 100) = roundCents(1995) = 1995
  assert.equal(totals.value.vat, 1995);
  // total = 9500 - 0 + 1995 = 11495
  assert.equal(totals.value.total, 11495);
});

test('invoiceTotals calculates VAT on amount after discount', () => {
  const invoice = createInvoice({
    customerId: 'C-002', // Standard (0% discount)
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 10 }], // 95000, 10% discount = 9500, net = 85500
  }).value;

  const totals = invoiceTotals(invoice);

  assert.equal(totals.ok, true);
  assert.equal(totals.value.subtotal, 95000);
  assert.equal(totals.value.discount, 9500);
  // vat = roundCents(85500 * 21 / 100) = roundCents(17955) = 17955
  assert.equal(totals.value.vat, 17955);
  // total = 95000 - 9500 + 17955 = 103455
  assert.equal(totals.value.total, 103455);
});

test('invoiceTotals handles different VAT rates', () => {
  const invoice = createInvoice({
    customerId: 'C-002', // Standard (0% discount)
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 1 }, // 21% VAT
      { sku: 'PRINT-A4', qty: 100 }, // 9% VAT
      { sku: 'WORKSHOP-DAY', qty: 1 }, // 0% VAT
    ],
  }).value;

  const totals = invoiceTotals(invoice);

  assert.equal(totals.ok, true);
  // DEV-HOUR: 9500, vat = 1995
  // PRINT-A4: 3700, vat = 333
  // WORKSHOP-DAY: 600000, vat = 0
  // total vat = 1995 + 333 + 0 = 2328
  assert.equal(totals.value.vat, 2328);
  // subtotal = 9500 + 3700 + 600000 = 613200
  // total = 613200 - 0 + 2328 = 615528
  assert.equal(totals.value.total, 615528);
});

test('invoiceTotals handles VAT rounding per line', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'X', qty: 1, name: 'X', unitPrice: 1000, vatRate: 21, discountPercent: 0 }, // vat = 210
      { sku: 'Y', qty: 1, name: 'Y', unitPrice: 1001, vatRate: 21, discountPercent: 0 }, // vat = 210.21, rounds to 210
    ],
  };

  const totals = invoiceTotals(invoice);

  assert.equal(totals.ok, true);
  // subtotal = 1000 + 1001 = 2001
  assert.equal(totals.value.subtotal, 2001);
  // vat line 1 = roundCents(1000 * 21 / 100) = 210
  // vat line 2 = roundCents(1001 * 21 / 100) = roundCents(210.21) = 210
  // total vat = 420
  assert.equal(totals.value.vat, 420);
});

test('invoiceTotals with multiple lines and mixed discounts/VAT', () => {
  const invoice = createInvoice({
    customerId: 'C-001', // Gold (5%)
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 5 }, // 47500, 5% discount = 2375, net = 45125, VAT 21% = 9476
      { sku: 'PRINT-A4', qty: 100, discountPercent: 0 }, // 3700, no extra discount, net = 3700, VAT 9% = 333
    ],
  }).value;

  const totals = invoiceTotals(invoice);

  assert.equal(totals.ok, true);
  // subtotal = 47500 + 3700 = 51200
  assert.equal(totals.value.subtotal, 51200);
  // discount = 2375 + 0 = 2375
  assert.equal(totals.value.discount, 2375);
  // vat = 9476 + 333 = 9809
  assert.equal(totals.value.vat, 9809);
  // total = 51200 - 2375 + 9809 = 58634
  assert.equal(totals.value.total, 58634);
});

test('addLine adds a new line to a draft invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  }).value;

  const result = addLine(invoice, { sku: 'DES-HOUR', qty: 3 });

  assert.equal(result.ok, true);
  assert.equal(result.value.lines.length, 2);
  assert.equal(result.value.lines[0].sku, 'DEV-HOUR');
  assert.equal(result.value.lines[0].qty, 5);
  assert.equal(result.value.lines[1].sku, 'DES-HOUR');
  assert.equal(result.value.lines[1].qty, 3);
  assert.equal(result.value.lines[1].name, 'Design work (hour)');
  assert.equal(result.value.lines[1].unitPrice, 8500);
});

test('addLine increases qty when SKU already exists', () => {
