  assert.equal(result.ok, true);
  const logoLine = result.value.lines[1];
  assert.equal(logoLine.sku, 'LOGO-PACK');
  assert.equal(logoLine.name, 'Logo package');
  assert.equal(logoLine.qty, 1);
  assert.equal(logoLine.unitPrice, 120000);
  assert.equal(logoLine.vatRate, 21);
});

test('addLine reports NOT_DRAFT for non-draft invoices', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'sent',
    lines: [{ sku: 'DEV-HOUR', qty: 5, name: 'Dev', unitPrice: 9500, vatRate: 21 }],
  };

  assert.deepEqual(addLine(invoice, { sku: 'DES-HOUR', qty: 1 }), {
    ok: false,
    error: 'NOT_DRAFT',
  });
});

test('addLine reports QTY_INVALID for invalid quantities', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  }).value;

  assert.deepEqual(addLine(invoice, { sku: 'DES-HOUR', qty: 0 }), {
    ok: false,
    error: 'QTY_INVALID',
  });

  assert.deepEqual(addLine(invoice, { sku: 'DES-HOUR', qty: -1 }), {
    ok: false,
    error: 'QTY_INVALID',
  });

  assert.deepEqual(addLine(invoice, { sku: 'DES-HOUR', qty: 3.5 }), {
    ok: false,
    error: 'QTY_INVALID',
  });
});

test('addLine reports UNKNOWN_SKU for missing product', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  }).value;

