    ok: false,
    error: 'UNKNOWN_SKU',
  });
});

test('addLine does not mutate the input invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  }).value;

  const originalLineCount = invoice.lines.length;
  const originalQty = invoice.lines[0].qty;

  addLine(invoice, { sku: 'DEV-HOUR', qty: 3 });

  assert.equal(invoice.lines.length, originalLineCount);
  assert.equal(invoice.lines[0].qty, originalQty);
});

test('removeLine removes a line from a draft invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 5 },
      { sku: 'DES-HOUR', qty: 3 },
    ],
  }).value;

  const result = removeLine(invoice, 'DES-HOUR');

  assert.equal(result.ok, true);
  assert.equal(result.value.lines.length, 1);
  assert.equal(result.value.lines[0].sku, 'DEV-HOUR');
});

test('removeLine reports NOT_DRAFT for non-draft invoices', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'sent',
    lines: [
      { sku: 'DEV-HOUR', qty: 5, name: 'Dev', unitPrice: 9500, vatRate: 21 },
      { sku: 'DES-HOUR', qty: 3, name: 'Des', unitPrice: 8500, vatRate: 21 },
    ],
  };

  assert.deepEqual(removeLine(invoice, 'DES-HOUR'), { ok: false, error: 'NOT_DRAFT' });
});

test('removeLine reports LINE_NOT_FOUND for missing SKU', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  }).value;

  assert.deepEqual(removeLine(invoice, 'NONEXISTENT'), {
    ok: false,
    error: 'LINE_NOT_FOUND',
  });
});

test('removeLine reports NO_LINES when removing the last line', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  }).value;

  assert.deepEqual(removeLine(invoice, 'DEV-HOUR'), {
    ok: false,
    error: 'NO_LINES',
  });
});

test('removeLine does not mutate the input invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 5 },
      { sku: 'DES-HOUR', qty: 3 },
    ],
  }).value;

  const originalLineCount = invoice.lines.length;

  removeLine(invoice, 'DES-HOUR');

  assert.equal(invoice.lines.length, originalLineCount);
});

test('removeLine maintains other lines unchanged', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 5 },
      { sku: 'DES-HOUR', qty: 3 },
      { sku: 'COPY-HOUR', qty: 2 },
    ],
  }).value;

  const result = removeLine(invoice, 'DES-HOUR');

  assert.equal(result.ok, true);
  assert.equal(result.value.lines.length, 2);
  assert.equal(result.value.lines[0].sku, 'DEV-HOUR');
  assert.equal(result.value.lines[0].qty, 5);
  assert.equal(result.value.lines[1].sku, 'COPY-HOUR');
  assert.equal(result.value.lines[1].qty, 2);
});

test('addLine and removeLine can be chained', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  }).value;

  const added = addLine(invoice, { sku: 'DES-HOUR', qty: 3 });
  assert.equal(added.ok, true);

  const removed = removeLine(added.value, 'DEV-HOUR');
  assert.equal(removed.ok, true);
  assert.equal(removed.value.lines.length, 1);
  assert.equal(removed.value.lines[0].sku, 'DES-HOUR');
});

