});

test('issueInvoice does not mutate the input invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  }).value;

  issueInvoice(invoice, []);

  assert.equal(invoice.status, 'draft');
  assert.equal(invoice.number, undefined);
});

test('issueInvoice works with modified invoices', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  }).value;

  const modified = addLine(invoice, { sku: 'DES-HOUR', qty: 3 }).value;
  const result = issueInvoice(modified, ['INV-2026-0001']);

  assert.equal(result.ok, true);
  assert.equal(result.value.number, 'INV-2026-0002');
  assert.equal(result.value.lines.length, 2);
