    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 5 },
      { sku: 'DES-HOUR', qty: 3 },
    ],
  }).value;

  const result = removeLine(invoice, 'DES-HOUR');

  assert.equal(result.ok, true);
  assert.equal(result.value.lines.length, 1);
  assert.equal(result.value.lines[0].sku, 'DEV-HOUR');
});

test('removeLine reports NOT_DRAFT for non-draft invoices', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'sent',
    lines: [
      { sku: 'DEV-HOUR', qty: 5, name: 'Dev', unitPrice: 9500, vatRate: 21 },
      { sku: 'DES-HOUR', qty: 3, name: 'Des', unitPrice: 8500, vatRate: 21 },
    ],
  };

  assert.deepEqual(removeLine(invoice, 'DES-HOUR'), { ok: false, error: 'NOT_DRAFT' });
});

test('removeLine reports LINE_NOT_FOUND for missing SKU', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  }).value;

  assert.deepEqual(removeLine(invoice, 'NONEXISTENT'), {
    ok: false,
    error: 'LINE_NOT_FOUND',
  });
});

test('removeLine reports NO_LINES when removing the last line', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  }).value;

  assert.deepEqual(removeLine(invoice, 'DEV-HOUR'), {
    ok: false,
    error: 'NO_LINES',
  });
});

test('removeLine does not mutate the input invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 5 },
      { sku: 'DES-HOUR', qty: 3 },
    ],
  }).value;

  const originalLineCount = invoice.lines.length;

  removeLine(invoice, 'DES-HOUR');

  assert.equal(invoice.lines.length, originalLineCount);
});

test('removeLine maintains other lines unchanged', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 5 },
      { sku: 'DES-HOUR', qty: 3 },
      { sku: 'COPY-HOUR', qty: 2 },
    ],
  }).value;

  const result = removeLine(invoice, 'DES-HOUR');

  assert.equal(result.ok, true);
  assert.equal(result.value.lines.length, 2);
  assert.equal(result.value.lines[0].sku, 'DEV-HOUR');
  assert.equal(result.value.lines[0].qty, 5);
  assert.equal(result.value.lines[1].sku, 'COPY-HOUR');
  assert.equal(result.value.lines[1].qty, 2);
});

test('addLine and removeLine can be chained', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  }).value;

  const added = addLine(invoice, { sku: 'DES-HOUR', qty: 3 });
  assert.equal(added.ok, true);

  const removed = removeLine(added.value, 'DEV-HOUR');
  assert.equal(removed.ok, true);
  assert.equal(removed.value.lines.length, 1);
  assert.equal(removed.value.lines[0].sku, 'DES-HOUR');
});

test('issueInvoice assigns number and changes status to issued', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  }).value;

  const result = issueInvoice(invoice, []);

  assert.equal(result.ok, true);
  assert.equal(result.value.status, 'issued');
  assert.equal(result.value.number, 'INV-2026-0001');
});

test('issueInvoice increments counter from existing numbers', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  }).value;

  const existing = ['INV-2026-0001', 'INV-2026-0002'];
  const result = issueInvoice(invoice, existing);

  assert.equal(result.ok, true);
  assert.equal(result.value.number, 'INV-2026-0003');
});

test('issueInvoice respects the issue date year for numbering', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-12-31',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  }).value;

  const existing = ['INV-2026-0005'];
  const result = issueInvoice(invoice, existing);

  assert.equal(result.ok, true);
  assert.equal(result.value.number, 'INV-2025-0001');
});

test('issueInvoice reports NOT_DRAFT for non-draft invoices', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'issued',
    number: 'INV-2026-0001',
    lines: [{ sku: 'DEV-HOUR', qty: 5, name: 'Dev', unitPrice: 9500, vatRate: 21 }],
  };

  assert.deepEqual(issueInvoice(invoice, []), { ok: false, error: 'NOT_DRAFT' });
});

test('issueInvoice preserves other invoice properties', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 5 },
      { sku: 'DES-HOUR', qty: 3 },
    ],
  }).value;

  const result = issueInvoice(invoice, []);

  assert.equal(result.ok, true);
  assert.equal(result.value.customerId, 'C-003');
  assert.equal(result.value.issueDate, '2026-10-07');
  assert.equal(result.value.lines.length, 2);
});

test('issueInvoice does not mutate the input invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  }).value;

  issueInvoice(invoice, []);

  assert.equal(invoice.status, 'draft');
  assert.equal(invoice.number, undefined);
});

test('issueInvoice works with modified invoices', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  }).value;

  const modified = addLine(invoice, { sku: 'DES-HOUR', qty: 3 }).value;
  const result = issueInvoice(modified, ['INV-2026-0001']);

  assert.equal(result.ok, true);
  assert.equal(result.value.number, 'INV-2026-0002');
  assert.equal(result.value.lines.length, 2);
});

