  // Total: 73000 - 3650 + 14564 = 83914
  assert.equal(totals.value.subtotal, 73000);
  assert.equal(totals.value.discount, 3650);
  assert.equal(totals.value.vat, 14564);
  assert.equal(totals.value.total, 83914);
});

