test('addLine and removeLine can be chained', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  }).value;

  const added = addLine(invoice, { sku: 'DES-HOUR', qty: 3 });
  assert.equal(added.ok, true);

  const removed = removeLine(added.value, 'DEV-HOUR');
  assert.equal(removed.ok, true);
  assert.equal(removed.value.lines.length, 1);
  assert.equal(removed.value.lines[0].sku, 'DES-HOUR');
});

test('issueInvoice assigns number and changes status to issued', () => {
